// Un reducer pur : (state, action) => nouvel état. Aucune mutation.
export function reducer(state, action) {
  switch (action.type) {
    case 'inc':
      // BUG : ajoute 1 au lieu du pas (state.step).
      return { ...state, count: state.count + 1 };
    case 'setStep':
      return { ...state, step: action.step };
    case 'reset':
      // BUG : ne réinitialise pas le pas.
      return { ...state, count: 0 };
    default:
      return state;
  }
}

